CREATE FUNCTION hiring_private.hiring_application_questions(_job_id uuid) RETURNS TABLE(id uuid,label text,type text,options jsonb,required boolean,section text,sort_order integer,max_length integer,help_text text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT q.id,coalesce(q.label_override,b.label,'Question'),q.type,coalesce(q.options,b.options),q.required,q.section,q.sort_order,coalesce(b.max_length,CASE WHEN q.section='Practical task' THEN 500 WHEN q.type IN ('link','video_link') THEN 2048 ELSE 3000 END),b.help_text FROM public.job_questions q LEFT JOIN public.question_bank b ON b.id=q.question_id WHERE q.job_id=_job_id AND auth.uid() IS NOT NULL AND (public.hiring_can_apply(_job_id,auth.uid()) OR EXISTS(SELECT 1 FROM public.applications WHERE job_id=_job_id AND candidate_id=auth.uid())) ORDER BY q.sort_order $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_application_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION hiring_private.hiring_application_questions(uuid) TO authenticated,service_role;
CREATE FUNCTION public.hiring_application_questions(_job_id uuid) RETURNS TABLE(id uuid,label text,type text,options jsonb,required boolean,section text,sort_order integer,max_length integer,help_text text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM hiring_private.hiring_application_questions(_job_id) $$;
REVOKE ALL ON FUNCTION public.hiring_application_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hiring_application_questions(uuid) TO authenticated,service_role;
CREATE FUNCTION public.hiring_candidate_fields_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF length(NEW.full_name)>100 OR length(NEW.area)>150 OR length(NEW.education)>300 OR length(NEW.current_occupation)>300 THEN RAISE EXCEPTION 'Personal details are too long'; END IF;
 IF coalesce(NEW.phone,'')<>'' AND NEW.phone !~ '^(\+8801|01)[3-9][0-9]{8}$' THEN RAISE EXCEPTION 'Enter a valid Bangladesh phone number'; END IF;
 IF coalesce(NEW.whatsapp,'')<>'' AND NEW.whatsapp !~ '^(\+8801|01)[3-9][0-9]{8}$' THEN RAISE EXCEPTION 'Enter a valid Bangladesh WhatsApp number'; END IF;
 RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hiring_candidate_fields_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hiring_candidate_fields BEFORE INSERT OR UPDATE ON public.candidates FOR EACH ROW EXECUTE FUNCTION public.hiring_candidate_fields_guard();